package ai.decisionos.aside;
import android.content.*;import android.os.Bundle;import org.json.*;
final class ChatWorkChecks {
 static void run(GoalInstrumentation i){Bundle out=new Bundle();try{Context c=i.getTargetContext();String phase=i.scenario.getString("chatWorkPhase","home");android.content.SharedPreferences prefs=c.getSharedPreferences("chat_work_checks",0);String goal="";try(GoalStore g=new GoalStore(c)){for(JSONObject row:g.goals())if(!GoalStore.fixture(row)&&row.optString("character").equals("grades")){goal=row.optString("id");break;}}i.check(!goal.isEmpty(),"existing school goal");
 if(phase.equals("visual")){String id=prefs.getString("home","");GoalAgentActivity a=(GoalAgentActivity)i.startActivitySync(new Intent(c,GoalAgentActivity.class).putExtra("goal_id",goal).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));i.runOnMainSync(()->a.chat.companion.select("홈"));Thread.sleep(2500);saveShot(i,c,"chat-home.png");i.runOnMainSync(()->a.chat.companion.tossHome.web.evaluateJavascript("NubiHome.scheduled("+JSONObject.quote(id)+")",null));Thread.sleep(2500);i.check(a.chat.input.getText().length()==0,"home alert sends instead of leaving draft");i.check(a.chat.history.toString().contains("scheduled-"+id),"home JS alert routes existing conversation");i.check(a.chat.messages.getChildCount()<=a.chat.history.length()+2,"no appended school news card list hiding answers");saveShot(i,c,"chat-result.png");JSONArray original=new JSONArray(a.chat.history.toString());String prompt="2099-01-01T12:00에 학식 조회 알림 예약";i.runOnMainSync(()->ScheduledWorkUi.handle(a.chat,prompt));i.check(a.chat.history.toString().contains("시작할 미래"),"invalid future deadline explained in chat");String stamp=java.time.LocalDateTime.now(java.time.ZoneId.of("Asia/Seoul")).plusDays(1).withSecond(0).withNano(0).toString();i.runOnMainSync(()->ScheduledWorkUi.handle(a.chat,stamp+" REGRESSION_CHAT_CANCEL_0622 학식 조회 알림 예약"));String cancel="";try(ScheduledWorkStore s=new ScheduledWorkStore(c)){for(JSONObject r:s.list())if(r.optString("title").contains("REGRESSION_CHAT_CANCEL_0622"))cancel=r.optString("id");}i.check(!cancel.isEmpty(),"chat creates scheduled work without form");final String title;try(ScheduledWorkStore s=new ScheduledWorkStore(c)){title=s.get(cancel).optString("title");}i.runOnMainSync(()->ScheduledWorkUi.handle(a.chat,"알림 "+title+" 취소"));try(ScheduledWorkStore s=new ScheduledWorkStore(c)){i.check(s.get(cancel).optString("state").equals("CANCELLED"),"chat cancels scheduled work");s.getWritableDatabase().delete("work","id=?",new String[]{cancel});}i.runOnMainSync(()->{a.store.saveConversation(a.chat.conversationId,original,"");a.chat.syncRun();});out.putString("stream","PASS "+i.checks+" final UI and chat scheduling checks\n");}
 else if(phase.equals("cleanup")){try(ScheduledWorkStore s=new ScheduledWorkStore(c);GoalStore g=new GoalStore(c)){for(String key:new String[]{"home","deadline"}){String id=prefs.getString(key,"");if(id.isEmpty())continue;ScheduledWork.cancel(c,id);JSONObject w=s.get(id);String cid=w.optString("conversation_id");if(!cid.isEmpty()){JSONObject row=g.workspaceRow("conversations",cid);JSONArray old=row.optJSONArray("messages"),keep=new JSONArray();for(int n=0;old!=null&&n<old.length();n++)if(!id.equals(old.optJSONObject(n).optString("scheduledWorkId")))keep.put(old.optJSONObject(n));GoalStore.put(row,"messages",keep);g.saveWorkspace("conversations",row);}s.getWritableDatabase().delete("work","id=?",new String[]{id});}}prefs.edit().clear().commit();out.putString("stream","PASS fixture cleanup\n");}
 else if(phase.equals("deadline")){long now=System.currentTimeMillis();String id;try(ScheduledWorkStore s=new ScheduledWorkStore(c)){id=s.create(goal,"REGRESSION_CHAT_DEADLINE_0622","2026-11-03 유니스트 학식 메뉴 실제 조회하고 출처와 단백질 메뉴 후보를 알려줘. 구매하지 마.","reminder","",now+12000,now);}prefs.edit().putString("deadline",id).commit();ScheduledWork.arm(c,id);c.startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));out.putString("stream","PASS scheduled real OS alarm; app backgrounded\n");}
 else if(phase.equals("home")){long now=System.currentTimeMillis();String id;try(ScheduledWorkStore s=new ScheduledWorkStore(c)){id=s.create(goal,"REGRESSION_CHAT_HOME_0622","2026-11-03 유니스트 학식 메뉴 실제 조회하고 출처를 알려줘. 구매하지 마.","reminder","",now+60000,now);}prefs.edit().putString("home",id).commit();final String ownGoal=goal,ownId=id;GoalAgentActivity a=(GoalAgentActivity)i.startActivitySync(new Intent(c,GoalAgentActivity.class).putExtra("goal_id",goal).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));i.runOnMainSync(()->{a.chat.companion.select("홈");ScheduledWorkUi.openFromHome(a.chat,ownId);});Thread.sleep(1200);i.check(!a.chat.conversationId.isEmpty(),"home tap opens owned conversation");try(ScheduledWorkStore s=new ScheduledWorkStore(c)){JSONObject r=s.get(id);i.check(r.optString("conversation_id").equals(a.chat.conversationId),"conversation persisted");ChatWork.enqueue(c,id);i.check(s.get(id).optString("request_id").equals(id),"duplicate tap same request id");}out.putString("stream","PASS "+i.checks+" home tap auto send checks\n");}
 else {String key=phase.equals("verifyDeadline")?"deadline":"home",id=prefs.getString(key,"");JSONObject work=new JSONObject();for(int n=0;n<150;n++){try(ScheduledWorkStore s=new ScheduledWorkStore(c)){work=s.get(id);}if(work.optString("state").equals("RESULT_READY")||work.optString("state").equals("FAILED"))break;Thread.sleep(1000);}i.check(work.optString("state").equals("RESULT_READY"),"actual Qwen completed: "+work.toString());i.check(!work.optString("job_id").isEmpty(),"actual server job ID");try(GoalStore g=new GoalStore(c)){JSONArray messages=g.workspaceRow("conversations",work.optString("conversation_id")).optJSONArray("messages");int users=0,assistants=0;for(int n=0;n<messages.length();n++){JSONObject m=messages.optJSONObject(n);if(!id.equals(m.optString("scheduledWorkId")))continue;if(m.optString("role").equals("user"))users++;else{assistants++;i.check(m.optString("state").equals("completed")&&!m.optString("text").isEmpty(),"answer in same conversation");}}i.check(users==1&&assistants==1,"exactly one bot request and result");JSONArray stale=new JSONArray();for(int n=0;n<messages.length();n++)if(!messages.optJSONObject(n).has("scheduledWorkId"))stale.put(messages.optJSONObject(n));g.saveConversation(work.optString("conversation_id"),stale,"");i.check(g.workspaceRow("conversations",work.optString("conversation_id")).optJSONArray("messages").length()>=2,"stale UI save preserves bot messages");}if(key.equals("deadline")){i.check(work.optInt("dispatch_count")==1,"one real alarm dispatch");ScheduledWork.fire(c,id);try(ScheduledWorkStore s=new ScheduledWorkStore(c)){i.check(s.get(id).optInt("dispatch_count")==1,"duplicate alarm ignored");}}out.putString("stream","PASS "+i.checks+" actual Qwen "+key+" checks\n"+work.toString()+"\n");}
 }catch(Throwable e){out.putString("stream","FAIL "+e+"\n");}i.finish(out.getString("stream","").startsWith("PASS")?-1:0,out);}
 static void saveShot(GoalInstrumentation i,Context c,String name)throws Exception{android.graphics.Bitmap bitmap=i.getUiAutomation().takeScreenshot();try(java.io.OutputStream f=new java.io.FileOutputStream(new java.io.File(c.getCacheDir(),name))){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}bitmap.recycle();}
}
